import{_ as a,o,c as i,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Efficient Ceph Performance Troubleshooting in Production Using eBPF - Dongdong Tao, Canonical","description":"","frontmatter":{"title":"Efficient Ceph Performance Troubleshooting in Production Using eBPF - Dongdong Tao, Canonical","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph","eBPF","Performance Monitoring","Storage Optimization","Distributed Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Efficient_Ceph_Performance_Troubleshooting_in_Production_Using_eBPF_-_Dongdong_Tao_Canonical.md","filePath":"posts/2025/Efficient_Ceph_Performance_Troubleshooting_in_Production_Using_eBPF_-_Dongdong_Tao_Canonical.md","lastUpdated":1780459816000}'),r={name:"posts/2025/Efficient_Ceph_Performance_Troubleshooting_in_Production_Using_eBPF_-_Dongdong_Tao_Canonical.md"};function t(n,e,c,d,h,s){return o(),i("div",null,[...e[0]||(e[0]=[l('<h3 id="ceph性能生产故障排除研讨会纪要" tabindex="-1">Ceph性能生产故障排除研讨会纪要 <a class="header-anchor" href="#ceph性能生产故障排除研讨会纪要" aria-label="Permalink to &quot;Ceph性能生产故障排除研讨会纪要&quot;">​</a></h3><h2 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h2><p>本次研讨会由Dongdong Tao主持，介绍了其开发的Ceph Safe Trace项目，这是一个基于eBPF的强大性能追踪工具集，用于高效诊断Ceph集群性能问题。研讨会通过实际生产案例展示了这些工具如何显著提升性能故障排查效率。</p><h2 id="关键讨论点" tabindex="-1">关键讨论点 <a class="header-anchor" href="#关键讨论点" aria-label="Permalink to &quot;关键讨论点&quot;">​</a></h2><h3 id="_1-ceph性能问题现状" tabindex="-1">1. Ceph性能问题现状 <a class="header-anchor" href="#_1-ceph性能问题现状" aria-label="Permalink to &quot;1. Ceph性能问题现状&quot;">​</a></h3><ul><li>性能问题可能表现为：慢请求、IOPS下降和延迟增加。</li><li>传统排查方法（如<code>perf dump</code>和调试日志）效率低下，缺乏对操作全生命周期(<code>life cycle latency</code>)的测量能力。</li></ul><h3 id="_2-safe-trace项目核心" tabindex="-1">2. Safe Trace项目核心 <a class="header-anchor" href="#_2-safe-trace项目核心" aria-label="Permalink to &quot;2. Safe Trace项目核心&quot;">​</a></h3><ul><li>设计目标：测量OSD操作的<code>life cycle latency</code>，准确定位IO路径中的瓶颈。</li><li>技术实现：通过eBPF程序在关键函数（如<code>inq_op</code>/<code>dq_op</code>）注入时间戳，结合<code>client ID</code>和<code>request ID</code>关联同一IO操作。</li></ul><h3 id="_3-主要工具介绍" tabindex="-1">3. 主要工具介绍 <a class="header-anchor" href="#_3-主要工具介绍" aria-label="Permalink to &quot;3. 主要工具介绍&quot;">​</a></h3><h4 id="osd-trace" tabindex="-1">OSD Trace <a class="header-anchor" href="#osd-trace" aria-label="Permalink to &quot;OSD Trace&quot;">​</a></h4><ul><li>功能：追踪任意Ceph OSD进程，输出每个IO操作的详细生命周期延迟。</li><li>延迟分解：包括Messenger层、OSD层、BlueStore层和关键指标。</li></ul><h4 id="rados-trace" tabindex="-1">Rados Trace <a class="header-anchor" href="#rados-trace" aria-label="Permalink to &quot;Rados Trace&quot;">​</a></h4><ul><li>特点：可追踪任意librados-based客户端（如VM、Cinder、RGW等）。</li><li>输出信息：进程ID、客户端ID、PG ID、参与的OSD、端到端延迟等。</li></ul><h3 id="_4-生产案例分享" tabindex="-1">4. 生产案例分享 <a class="header-anchor" href="#_4-生产案例分享" aria-label="Permalink to &quot;4. 生产案例分享&quot;">​</a></h3><ul><li>案例1：高尾延迟问题，通过OSD Trace发现网络路径问题。</li><li>案例2：EC镜像克隆性能问题，通过优化<code>extent_cmp</code>操作，性能提升显著。</li></ul><h3 id="_5-容器化支持" tabindex="-1">5. 容器化支持 <a class="header-anchor" href="#_5-容器化支持" aria-label="Permalink to &quot;5. 容器化支持&quot;">​</a></h3><ul><li>已支持通过<code>cephadm</code>部署的容器化进程追踪。</li><li>无需安装调试符号，最低内核版本要求：5.8。</li></ul><h2 id="演示环节" tabindex="-1">演示环节 <a class="header-anchor" href="#演示环节" aria-label="Permalink to &quot;演示环节&quot;">​</a></h2><ul><li>问题复现：通过fio测试显示SSD集群出现高尾延迟。</li><li>诊断流程：使用Rados Trace定位问题OSD，再用OSD Trace确认瓶颈。</li><li>修复验证：修复网络问题后，高尾延迟消失。</li></ul><h2 id="未来计划" tabindex="-1">未来计划 <a class="header-anchor" href="#未来计划" aria-label="Permalink to &quot;未来计划&quot;">​</a></h2><ul><li>开发<code>MDS Trace</code>：追踪MDS请求的生命周期延迟。</li><li>实现<code>kernel FS trace</code>：追踪CephFS内核客户端的元数据IO。</li><li>扩展平台支持：已验证Ubuntu/CentOS Stream，计划支持更多Linux发行版。</li></ul><h2 id="问答环节" tabindex="-1">问答环节 <a class="header-anchor" href="#问答环节" aria-label="Permalink to &quot;问答环节&quot;">​</a></h2><ul><li>依赖项：极简（主要用C/C++实现，无需BCC）。</li><li>RocksDB设备监控：理论上可通过eBPF注入实现（待开发）。</li><li>性能影响：单OSD追踪对IOPS影响可忽略。</li></ul><h2 id="后续行动" tabindex="-1">后续行动 <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动&quot;">​</a></h2><ul><li>推广工具使用：项目已开源（GitHub仓库提供）。</li><li>欢迎社区贡献：包括测试框架开发和多平台适配。</li><li>参考资源：Ceph AC 2023演讲材料、项目README中的操作指南。</li></ul><p>研讨会以掌声结束，与会者对工具的实际价值表示高度认可。</p>',26)])])}const f=a(r,[["render",t]]);export{u as __pageData,f as default};
